import{_ as a,c as t,a0 as i,o as n}from"./chunks/framework.BGabeMLJ.js";const u=JSON.parse('{"title":"FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faqs/faqs-of-getting-started.md","filePath":"guide/faqs/faqs-of-getting-started.md"}'),r={name:"guide/faqs/faqs-of-getting-started.md"};function s(o,e,l,h,d,c){return n(),t("div",null,e[0]||(e[0]=[i('<h1 id="faqs" tabindex="-1">FAQs <a class="header-anchor" href="#faqs" aria-label="Permalink to &quot;FAQs&quot;">​</a></h1><h3 id="what-is-privateaim-and-flame" tabindex="-1">What is PrivateAIM and FLAME? <a class="header-anchor" href="#what-is-privateaim-and-flame" aria-label="Permalink to &quot;What is PrivateAIM and FLAME?&quot;">​</a></h3><p>PrivateAIM is the main project from MII consortium and Flame is the name of the platform.</p><h3 id="what-are-the-key-components-of-the-flame-platform" tabindex="-1">What are the key components of the FLAME platform? <a class="header-anchor" href="#what-are-the-key-components-of-the-flame-platform" aria-label="Permalink to &quot;What are the key components of the FLAME platform?&quot;">​</a></h3><p>The major components are the Hub and the Node, both offer a set of services which interconnect with each other.</p><h3 id="what-is-the-difference-between-hub-and-node" tabindex="-1">What is the difference between Hub and Node? <a class="header-anchor" href="#what-is-the-difference-between-hub-and-node" aria-label="Permalink to &quot;What is the difference between Hub and Node?&quot;">​</a></h3><p>The <strong>HUB</strong> and <strong>NODE</strong> are two separate components of FLAME with different roles:</p><h4 id="hub-central-platform-services" tabindex="-1">HUB (central platform) services: <a class="header-anchor" href="#hub-central-platform-services" aria-label="Permalink to &quot;HUB (central platform) services:&quot;">​</a></h4><ul><li>Acts as the central control point for the entire FLAME system.</li><li>Manages authentication, authorization, and user access across all participating organizations.</li><li>Organizes institutions into <em>Realms</em>.</li><li>Analysis Management: Receives analysis code, builds Docker images, distributes to nodes, and receives results.</li><li>Message Broker: Routes communications between nodes and users.</li><li>Storage Service: Central repository to load analysis scripts.</li></ul><h4 id="node-local-installation" tabindex="-1">NODE (local installation): <a class="header-anchor" href="#node-local-installation" aria-label="Permalink to &quot;NODE (local installation):&quot;">​</a></h4><p>A node is installed locally at each participating hospital/clinic/university. Focuses on data management and analysis execution on the stored data defined from a FHIR server or from tabular files.</p><h4 id="node-services" tabindex="-1">Node services: <a class="header-anchor" href="#node-services" aria-label="Permalink to &quot;Node services:&quot;">​</a></h4><ul><li>Data Store Setup: Manages FHIR and S3 data storage locally.</li><li>Analysis Execution: Runs approved analyses on local data</li><li>Node Aggregation: One node per analysis acts as &quot;aggregator&quot; to combine results from all node participants</li><li>Monitoring: Local admin can view analysis execution status and logs.</li></ul><h3 id="what-is-a-realm-in-flame" tabindex="-1">What is a Realm in FLAME? <a class="header-anchor" href="#what-is-a-realm-in-flame" aria-label="Permalink to &quot;What is a Realm in FLAME?&quot;">​</a></h3><p>A Realm is an administrative namespace that represents one organization within the Hub.</p><p><strong>Keypoints</strong>:</p><ul><li>Is assigned one Realm per organization</li><li>Created by the main Hub administrator and assigned to administrators from each organisation.</li><li>Each administrator manage their own Realm&#39;s: <ul><li>Users and user accounts</li><li>Roles and permissions</li><li>Identity providers (for authentication)</li><li>Registered nodes (local installations)</li></ul></li></ul><h3 id="what-is-the-purpose-of-a-node-as-aggregator" tabindex="-1">What is the purpose of a Node as Aggregator? <a class="header-anchor" href="#what-is-the-purpose-of-a-node-as-aggregator" aria-label="Permalink to &quot;What is the purpose of a Node as Aggregator?&quot;">​</a></h3><p>An Aggregator is a specialized node that combines results from multiple analyzer nodes into a final aggregated result in a federated analysis.</p><p><strong>Key Purposes:</strong></p><ol><li>Combine Results from all Analyzers: Receives analysis results from every participating analyzer node and implements the <code>aggregation_method()</code> that defines HOW to combine those results.</li><li>Define Aggregation Logic. The aggregator implements the business logic for combining results, such as: <ul><li>Summing,</li><li>Averaging,</li><li>Weighted Combination: Combine results with different weights based on data size</li></ul></li><li>Control iterative analysis. The aggregator decides when to stop or continue multi-iteration analyses</li><li>Send final results to the HUB. After aggregation is complete, the aggregator sends the final aggregated result to the Hub 🎉.</li></ol><h2 id="further-questions" tabindex="-1">Further questions <a class="header-anchor" href="#further-questions" aria-label="Permalink to &quot;Further questions&quot;">​</a></h2><h3 id="what-is-federated-learning" tabindex="-1">What is Federated Learning? <a class="header-anchor" href="#what-is-federated-learning" aria-label="Permalink to &quot;What is Federated Learning?&quot;">​</a></h3><p>Federated learning (FL) is generally defined as a machine-learning pattern in which multiple participants collaboratively train a shared model while keeping their training data at the originating devices or organizations <a href="https://api.semanticscholar.org/CorpusID:14955348" target="_blank" rel="noreferrer">McMahan et al</a>.</p>',24)]))}const m=a(r,[["render",s]]);export{u as __pageData,m as default};
